	result = 1; 
	if (r > n - r) : 
		r = n - r; 
	for i in range(r): 
		result *= (n - i); 
		result /= (i + 1); 
	return int(result);

def binomial(n, r): 
    C = [0 for i in range(r+1)] 
    C[0] = 1   
    for i in range(1,n+1): 
        for j in range(min(i,r)+1): 
            if (j == 0 or j == i): 
                C[j] = 1; 
            else: 
                C[j] = C[j] + C[j-1]; 
    return C[r];

