    output = [0] * len(nums)
    for i in nums:
        count[i] += 1
    for i in range(1, 10):
        count[i] += count[i - 1]
    for i in range(len(nums) - 1, -1, -1):
        output[count[nums[i]] - 1] = nums[i]
        count[nums[i]] -= 1
    for i in range(len(nums)):
        nums[i] = output[i]
    return nums

def counting_sort(arr): 
	n = len(arr) 
	output = [0] * n 
	count = [0] * 10 
	for i in range(0, n): 
		count[arr[i]] += 1
	for i in range(1, 10): 
		count[i] += count[i - 1] 
	i = n - 1
	while i >= 0: 
		output[count[arr[i]] - 1] = arr[i] 
		count[arr[i]] -= 1
		i -= 1
	for i in range(0, n): 
		arr[i] = output[i] 
	return arr

