def counting_sort(arr):
    arr_len = len(arr)
    output = [0] * arr_len
    f_arr = [0] * 256
    for i in range(256):
        f_arr[i] = 0
    for i in range(0, arr_len):
        f_arr[arr[i]] = f_arr[arr[i]] + 1
    for i in range(1, 256):
        f_arr[i] = f_arr[i - 1] + f_arr[i]
    for i in range(arr_len - 1, -1, -1):
        output[f_arr[arr[i]] - 1] = arr[i]
        f_arr[arr[i]] = f_arr[arr[i]] - 1
    for i in range(arr_len):
        arr[i] = output[i]
    return arr

def count_sort(arr): 
    n = len(arr) 
    m = max(arr) 
    output = [0] * n 
    count = [0] * (m+1) 
    for i in range(0,n): 
        count[arr[i]] += 1
    for i in range(1,m+1): 
        count[i] += count[i-1] 
    for i in range(n-1,-1,-1): 
        output[count[arr[i]] - 1] = arr[i] 
        count[arr[i]] -= 1
    for i in range(0,n): 
        arr[i] = output[i] 
    return arr

def countingsort(arr):
    n = len(arr)
    m = max(arr) + 1
    count = [0] * m
    for i in range(n):
        count[arr[i]] += 1
    j = 0
    for i in range(m):
        while count[i] > 0:
            arr[j] = i
            j += 1
            count[i] -= 1
    return arr

