def find_Largest_Num(dig): 
    l = len(dig) 
    du = [0] * l 
    for i in range(l): 
        max = 0
        for j in range(l): 
            if dig[j] > dig[max]: 
                max = j 
        du[i] = dig[max] 
        dig[max] = -1
    s = "" 
    for i in du: 
        s += str(i) 
    return s

