def Max_Length_Diff_Subsequence(arr,n): 
    ans = 0
    for i in range(n - 1):
        if arr[i] == arr[i + 1]:
            continue
        else:
            ans = max(ans, abs(arr[i] - arr[i + 1]))
    return ans

def max_len(arr,n):
    bag = {}
    for i in range(n-1,-1,-1):
        for j in range(0,arr[i]):
            if(arr[i]-j in bag):
                bag[arr[i]] = max(bag[arr[i]],bag[arr[i]-j]+1)
            else:
                bag[arr[i]] = 1
    return max(bag.values())

