def max_len_subseq(arr,n):
    dp = [1] * n
    for i in range(1,n):
        for j in range(i):
            if arr[i]-arr[j] <= 1 and dp[i] < dp[j]+1:
                dp[i] = dp[j]+1
    return max(dp)

def max_length_subseq(arr,n):
  if (n == 0):
    return 0
  dp = [0 for i in range(n)]
  dp[0] = 1
  for i in range(1,n):
    dp[i] = 1
    for j in range(i):
      if (arr[i] > arr[j] and arr[i] - arr[j] >= 2):
        dp[i] = max(dp[i], dp[j] + 1)
  return max(dp)

def max_length(nums):
    dp = [1]*len(nums)
    result = 1
    for i in range(1, len(nums)):
        for j in range(0, i):
            if nums[i] - nums[j] == 1:
                dp[i] = max(dp[i], dp[j] + 1)
                result = max(result, dp[i])
    return result

def find_max_seq(arr, n) : 
	Len = [1 for i in range(n)] 
	for i in range(1, n) : 
		for j in range(i) : 
			if (arr[i] - arr[j] == 1) : 
				Len[i] = max(Len[i], Len[j] + 1) 
	return max(Len)
